// Meta sendet einen Hub-Challenge zur Verifizierung — sofort antworten
const query = items[0].json.query || {};
if (query['hub.mode'] === 'subscribe' && query['hub.verify_token'] === $env.INSTAGRAM_VERIFY_TOKEN) {
  return [{ json: { __verify: true, challenge: query['hub.challenge'] } }];
}

// Echte Webhook-Events verarbeiten
const body = items[0].json.body || items[0].json;
const events = [];

for (const entry of (body.entry || [])) {
  for (const change of (entry.changes || [])) {
    const val = change.value || {};

    // DM (messaging)
    if (change.field === 'messages' && val.messages) {
      for (const msg of val.messages) {
        if (msg.message && !msg.message.is_echo) {
          events.push({
            json: {
              platform:     'instagram',
              platform_id:  msg.id || '',
              event_type:   'dm',
              author:       val.sender?.id || '',
              author_email: '',
              subject:      'Instagram DM',
              content:      msg.message.text || '[Mediannachricht]',
              sender_id:    val.sender?.id || '',
              timestamp:    new Date(msg.timestamp * 1000).toISOString()
            }
          });
        }
      }
    }

    // Kommentare
    if (change.field === 'comments' && val.text) {
      events.push({
        json: {
          platform:    'instagram',
          platform_id: val.id || '',
          event_type:  'comment',
          author:      val.from?.username ? '@' + val.from.username : val.from?.id || '',
          author_email: '',
          subject:     'Instagram Kommentar',
          content:     val.text || '',
          sender_id:   val.from?.id || '',
          media_id:    val.media?.id || '',
          timestamp:   new Date().toISOString()
        }
      });
    }
  }
}

if (events.length === 0) return [];
return events;
